def push_cancelled_back(sizes):
    zeros = sizes.count(0)
    for _ in range(zeros):
        sizes.remove(0)
    sizes.extend([0] * zeros)
    return len(sizes) - zeros

def push_cancelled_back(sizes):
    i = 0
    while i < len(sizes):
        if sizes[i] == 0:
            del sizes[i]
            sizes.append(0)
        i += 1
    return len(sizes) - sizes.count(0)
